import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"NVMeoF in Ceph - Whats New and Performance Best Practices - Mike Burkhart & Aviv Caro, IBM","description":"","frontmatter":{"title":"NVMeoF in Ceph - Whats New and Performance Best Practices - Mike Burkhart & Aviv Caro, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","NVMe-oF","Storage Performance","Distributed Storage","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_Performance_Best_Practices_-_Mike_Burkhart_Aviv_Caro_IBM.md","filePath":"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_Performance_Best_Practices_-_Mike_Burkhart_Aviv_Caro_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2025/NVMeoF_in_Ceph_-_What_s_New_and_Performance_Best_Practices_-_Mike_Burkhart_Aviv_Caro_IBM.md"};function o(h,e,_,n,s,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="ceph-nvme-over-fabric-nvme-of-技术分享会议纪要" tabindex="-1">Ceph NVMe over Fabric (NVMe-oF) 技术分享会议纪要 <a class="header-anchor" href="#ceph-nvme-over-fabric-nvme-of-技术分享会议纪要" aria-label="Permalink to &quot;Ceph NVMe over Fabric (NVMe-oF) 技术分享会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li>主题：Ceph NVMe-oF 最新进展与性能最佳实践</li><li>主讲人：Mike Burkheart (IBM, NVMe-oF 产品经理) &amp; Aviv Carol (IBM, NVMe-oF 及 RBD 开发团队负责人)</li><li>主要内容：Ceph Tentacle 版本中 NVMe-oF 的首发支持，高可用性架构，性能优化，自动化改进等</li></ul><h4 id="关键讨论议题" tabindex="-1">关键讨论议题 <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;关键讨论议题&quot;">​</a></h4><h5 id="_1-ceph-tentacle-对-nvme-of-的支持" tabindex="-1">1. Ceph Tentacle 对 NVMe-oF 的支持 <a class="header-anchor" href="#_1-ceph-tentacle-对-nvme-of-的支持" aria-label="Permalink to &quot;1. Ceph Tentacle 对 NVMe-oF 的支持&quot;">​</a></h5><ul><li>首次上游集成，支持多网关部署，实现高可用性和负载均衡。</li><li>支持 Linux 和 VMware 发起端，要求 Linux kernel ≥5.4，VMware ≥8.0U3。</li></ul><h5 id="_2-高可用性-ha-设计" tabindex="-1">2. 高可用性（HA）设计 <a class="header-anchor" href="#_2-高可用性-ha-设计" aria-label="Permalink to &quot;2. 高可用性（HA）设计&quot;">​</a></h5><ul><li>使用 Paxos 服务监控网关状态，触发故障转移。</li><li>ANA 协议实现命名空间级别的读写隔离和负载均衡。</li></ul><h5 id="_3-安全与访问控制" tabindex="-1">3. 安全与访问控制 <a class="header-anchor" href="#_3-安全与访问控制" aria-label="Permalink to &quot;3. 安全与访问控制&quot;">​</a></h5><ul><li>支持单向和双向认证，密钥加密存储于 OMAP。</li><li>命名空间掩码支持精细化控制，限制主机访问特定命名空间。</li></ul><h5 id="_4-新功能与改进计划" tabindex="-1">4. 新功能与改进计划 <a class="header-anchor" href="#_4-新功能与改进计划" aria-label="Permalink to &quot;4. 新功能与改进计划&quot;">​</a></h5><ul><li>Kubernetes CSI 驱动开发中，目标支持 OpenShift。</li><li>自动化改进，合并元数据池与数据池管理，简化部署流程。</li><li>性能优化，缩短故障转移时间，CRC 校验复用，探索 DPU/SmartNIC 支持。</li></ul><h5 id="_5-性能测试结果" tabindex="-1">5. 性能测试结果 <a class="header-anchor" href="#_5-性能测试结果" aria-label="Permalink to &quot;5. 性能测试结果&quot;">​</a></h5><ul><li>在双路 32 核 CPU，24 NVMe 盘，4/8/12 节点集群上进行测试。</li><li>随机读写（70/30）测试中，12 网关组可达 100 万 IOPS，延迟 &lt;2ms。</li></ul><h4 id="问答环节摘要" tabindex="-1">问答环节摘要 <a class="header-anchor" href="#问答环节摘要" aria-label="Permalink to &quot;问答环节摘要&quot;">​</a></h4><ul><li>问答环节涵盖了 NVMe-oF 与 RBD 的性能对比，生产环境命名空间规划，DPU/SmartNIC 支持，池迁移工具兼容性等问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完善 Kubernetes CSI 驱动，实现 Active-Active 写入模式，扩展性能基准测试，补充文档等。</li></ul><h4 id="关键词保留-ceph-nvme-of-术语" tabindex="-1">关键词保留（Ceph/NVMe-oF 术语） <a class="header-anchor" href="#关键词保留-ceph-nvme-of-术语" aria-label="Permalink to &quot;关键词保留（Ceph/NVMe-oF 术语）&quot;">​</a></h4><ul><li>Ceph: CRUSH algorithm, OSD, MON, RADOS, librados, PG, bluestore</li><li>NVMe-oF: ANA protocol, SPDK, subsystem, namespace, initiator, QoS</li><li>存储：object storage, block storage (RBD), file system (CephFS)</li><li>高可用：failover, gateway group, Paxos</li><li>性能优化：failover time, CRC, DPU/SmartNIC</li><li>自动化：CLI, automation, Kubernetes CSI</li></ul>',20)])])}const m=a(l,[["render",o]]);export{d as __pageData,m as default};
